def draw_text(oled, x, y, text):
    """在 OLED 上繪製中文字串，每字 16x16"""
    for ch in text:
        if ch in FONT:
            data = FONT[ch]
            for row in range(16):
                val = (data[row * 2] << 8) | data[row * 2 + 1]
                for col in range(16):
                    if val & (1 << (15 - col)):
                        oled.pixel(x + col, y + row, 1)
            x += 16
        elif ch == ' ':
            x += 8
        else:
            # ASCII fallback: use built-in font
            oled.text(ch, x, y + 4, 1)
            x += 8
